    static void pickerStateTests(MainActivity m,StringBuilder report)throws Exception{
        ui(m,()->{
            boolean[] called={false};m.importCallback=files->called[0]=true;
            m.onActivityResult(900,android.app.Activity.RESULT_CANCELED,null);
            if(m.importCallback!=null||called[0])throw new IllegalStateException("Cancelled picker retained import callback");
            m.importCallback=files->called[0]=true;m.onActivityResult(900,android.app.Activity.RESULT_OK,new android.content.Intent());
            if(m.importCallback!=null||called[0]||m.busy)throw new IllegalStateException("Empty picker result launched import task");
            ArrayList<File> pending=new ArrayList<>();pending.add(new File(m.outputDir,"pending.png"));m.waitToSave(pending,"first feature");pending.clear();String previous=m.lastFeature;m.lastFeature="other feature";
            if(m.waitingOutputs.size()!=1||!m.waitingFeature.equals("first feature"))throw new IllegalStateException("Pending save adopted unrelated feature or mutated file list");
            m.folderPending=true;m.onActivityResult(901,android.app.Activity.RESULT_OK,new android.content.Intent());m.lastFeature=previous;
            if(m.waitingOutputs!=null||m.folderPending||!m.waitingFeature.isEmpty())throw new IllegalStateException("Empty folder result retained pending save");
        });
        report.append("PASS: cancelled/empty picker results clear callbacks and pending saves; save snapshots retain their feature and files\n");
    }
    static void scrambleDirectionTests(MainActivity m,File dir,StringBuilder report)throws Exception{
        File original=new File(dir,"原图.png");Files.Job job=new Files.Job();ArrayList<File> inputs=new ArrayList<>();
        for(int i=0;i<2;i++)inputs.add(Images.scramble(original,m.outputDir,false,0,0,job));
        ui(m,()->{m.showPage(1);m.cancelPreview();Files.Job pending=new Files.Job();m.previewJob=pending;m.showPage(1);if(pending.cancelled)throw new IllegalStateException("Same-page navigation cancelled preview");m.cancelPreview();m.state[1].entries.clear();m.scrambleReversePreview=false;Button batch=buttonNamed(m.pages[1],m.t("批量解混淆","Descramble all"));if(batch==null||!batch.performClick()||!m.scrambleReversePreview||m.busy)throw new IllegalStateException("Empty batch descramble button opened wrong action");});
        List<File> decoded=new ArrayList<>();CountDownLatch done=new CountDownLatch(1);
        ui(m,()->{m.showPage(1);m.cancelPreview();MainActivity.State state=m.state[1];state.entries.clear();for(File f:inputs)state.entries.add(new MainActivity.Entry(f));state.selected=0;m.refreshQueue(state);m.scrambleReversePreview=true;
            m.task(j->{ArrayList<File> outputs=new ArrayList<>();for(File f:inputs)outputs.add(Images.scramble(f,m.outputDir,true,0,0,j));return outputs;},files->{decoded.addAll(files);done.countDown();});});
        if(!done.await(20,TimeUnit.SECONDS)||decoded.size()!=2)throw new IOException("Descramble batch did not finish");
        ui(m,()->{if(!m.scrambleReversePreview)throw new IllegalStateException("Batch completion reverted to scramble preview");m.showPage(7);m.showPage(1);if(!m.scrambleReversePreview)throw new IllegalStateException("Page return reverted descramble preview");if(!m.scrambleAfter.getContentDescription().toString().startsWith(m.t("解混淆结果","Descrambled result")))throw new IllegalStateException("Descramble preview uses scramble label");m.cancelPreview();});
        Bitmap before=Images.load(original,0,true);try{int[] expected=new int[before.getWidth()*before.getHeight()];before.getPixels(expected,0,before.getWidth(),0,0,before.getWidth(),before.getHeight());for(File f:decoded){Bitmap after=Images.load(f,0,true);try{int[] pixels=new int[expected.length];after.getPixels(pixels,0,before.getWidth(),0,0,before.getWidth(),before.getHeight());if(!Arrays.equals(expected,pixels))throw new IOException("Batch inverse pixels differ");}finally{after.recycle();}}}finally{before.recycle();}
        report.append("PASS: two-file descramble restores exact pixels and retains inverse preview after task completion and page return\n");
    }
    static void ui(MainActivity m,Runnable action)throws Exception{CountDownLatch done=new CountDownLatch(1);Throwable[] failure={null};m.ui.post(()->{try{action.run();}catch(Throwable e){failure[0]=e;}finally{done.countDown();}});if(!done.await(10,TimeUnit.SECONDS))throw new IOException("UI timed out");if(failure[0]!=null)throw new IOException("UI test failed",failure[0]);}
    static void frames(MainActivity m)throws Exception{CountDownLatch done=new CountDownLatch(1);m.ui.post(()->m.root.postOnAnimation(()->m.root.postOnAnimation(done::countDown)));if(!done.await(10,TimeUnit.SECONDS))throw new IOException("Frame wait timed out");}
